def whole_reference(points: np.ndarray, mask: np.ndarray) -> np.ndarray:
    """The reference's average points on each input, rounded to whole points by the rule of every class. Given."""
    return np.floor(points[mask].mean(axis=0) + 0.5).astype(np.int64)


def _show_references() -> None:
    dec = S["decision"]
    marginal = reference_mask(dec.total_dev, dec.cut, MARGINAL_WIDTH)
    refs = {"all applicants": np.ones(N_DEV, dtype=bool), "at or just above the cut-off": marginal}
    S["refs"] = {name: mask for name, mask in refs.items()}
    S["ref_means"] = {name: whole_reference(dec.points_dev, mask) for name, mask in refs.items()}
    S["ref_exact"] = {name: dec.points_dev[mask].mean(axis=0) for name, mask in refs.items()}
    print(f"{'reference population':<30}{'rows':>8}{'share':>8}   average points of each input, in whole points")
    print(f"{'':<46}" + "".join(f"{name:>12}" for name in SHORT))
    for name, mask in refs.items():
        print(f"{name:<30}{int(mask.sum()):>8,}{mask.mean():>8.1%}   " + "".join(f"{v:>12d}" for v in S["ref_means"][name]))
    gap = S["ref_means"]["all applicants"] - S["ref_means"]["at or just above the cut-off"]
    print("\naverage points of the 'all applicants' reference minus the other, by input: "
          + ", ".join(f"{FEATURES[j]} {gap[j]:+d}" for j in range(P)))
    print("An applicant's shortfall on an input is the reference's average points minus the applicant's. Where the two")
    print("references' averages are far apart, the choice of reference can change which input an applicant falls short on.")


